-- Optional Lens showcase fixture. Synthetic data only; generated by docs/examples/generate_showcase.py.

-- Import ONCE after schema.sql. Requires datasource 1 to point to this database.

-- Adds independent tables and IDs 97101-97602; does not reset existing data. Do not use mysql --force.

SET NAMES utf8mb4;

CREATE TABLE `lens_demo_growth` (business_date DATE NOT NULL, region VARCHAR(20) NOT NULL, channel VARCHAR(20) NOT NULL, category VARCHAR(20) NOT NULL, orders INT NOT NULL, revenue DECIMAL(14,2) NOT NULL, profit DECIMAL(14,2) NOT NULL, PRIMARY KEY(business_date,region,channel,category)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `lens_demo_acquisition` (business_date DATE NOT NULL, channel VARCHAR(20) NOT NULL, visits INT NOT NULL, signups INT NOT NULL, activated INT NOT NULL, paid INT NOT NULL, spend DECIMAL(14,2) NOT NULL, revenue DECIMAL(14,2) NOT NULL, PRIMARY KEY(business_date,channel)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

START TRANSACTION;






















  business_date,
  region,
  channel,
  category,
  orders,
  revenue,
  profit
FROM lens_demo_growth','{}','EBL',1);




UNION ALL
SELECT business_date, channel, ''完成注册'' AS stage, 2 AS stage_order, signups AS people FROM lens_demo_acquisition
UNION ALL
SELECT business_date, channel, ''激活产品'' AS stage, 3 AS stage_order, activated AS people FROM lens_demo_acquisition
UNION ALL
SELECT business_date, channel, ''付费转化'' AS stage, 4 AS stage_order, paid AS people FROM lens_demo_acquisition','{}','EBL',1);


  business_date,
  CASE region WHEN ''华东'' THEN ''East'' WHEN ''华南'' THEN ''South'' WHEN ''华北'' THEN ''North'' WHEN ''西部'' THEN ''West'' ELSE region END AS region,
  CASE channel WHEN ''线上商城'' THEN ''Online'' WHEN ''品牌门店'' THEN ''Stores'' WHEN ''合作经销'' THEN ''Partners'' ELSE channel END AS channel,
  CASE category WHEN ''智能数码'' THEN ''Electronics'' WHEN ''户外运动'' THEN ''Outdoor'' WHEN ''家居生活'' THEN ''Home'' WHEN ''美妆个护'' THEN ''Beauty'' WHEN ''精品食品'' THEN ''Grocery'' ELSE category END AS category,
  orders,
  revenue,
  profit
FROM lens_demo_growth','{}','EBL',1);











































COMMIT;
